  "{installPath}/components/control/button/_impl/variants/selected_button_widget.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\nimport 'package:flutter/widgets.dart';\n\nimport '../../../../../shared/primitives/clickable.dart';\nimport '../../../../../shared/primitives/form_control.dart';\nimport '../../../../../shared/primitives/form_value_supplier.dart';\nimport '../../../../../shared/theme/theme.dart';\nimport '../styles/abstract_button_style.dart';\nimport '../styles/button_state_property.dart';\nimport '../styles/button_style_class.dart';\nimport '../core/button_widget.dart';\nimport '../state/selected_button_state.dart';\n\n/// SelectedButton defines a reusable type for this registry module.\nclass SelectedButton extends StatefulWidget {\n  /// The current selection state of the button.\n  final bool value;\n\n  /// Called when the selection state changes.\n  ///\n  /// If `null`, the button is disabled.\n  final ValueChanged<bool>? onChanged;\n\n  /// The widget displayed inside the button.\n  final Widget child;\n\n  /// The button style when not selected.\n  ///\n  /// Defaults to ghost style.\n  final AbstractButtonStyle style;\n\n  /// The button style when selected.\n  ///\n  /// Defaults to secondary style.\n  final AbstractButtonStyle selectedStyle;\n\n  /// Whether the button is enabled.\n  ///\n  /// If `null`, enabled state is determined by whether [onChanged] is non-null.\n  final bool? enabled;\n\n  /// The alignment of the child within the button.\n  final AlignmentGeometry? alignment;\n\n  /// The margin alignment for the button.\n  final AlignmentGeometry? marginAlignment;\n\n  /// Whether to disable style transition animations.\n  ///\n  /// Defaults to `false`. When `true`, style changes are instant.\n  final bool disableTransition;\n\n  /// Called when the hover state changes.\n  final ValueC