\": [\n        {\n          \"type\": \"number\",\n          \"name\": \"badgeSize\",\n          \"label\": \"Badge Size\",\n          \"description\": \"Badge Size in pixels (affected by theme.scaling).\",\n          \"defaultValue\": 12.0,\n          \"required\": false,\n          \"isAdvanced\": false,\n          \"visibleIf\": [],\n          \"validation\": {\n            \"clamp\": \"reject\",\n            \"min\": 0.0,\n            \"max\": 100.0,\n            \"step\": 1.0\n          },\n          \"ui\": {\n            \"control\": \"slider\",\n            \"unit\": \"px\"\n          },\n          \"since\": \"1.0.0\"\n        },\n        {\n          \"type\": \"number\",\n          \"name\": \"groupChildSize\",\n          \"label\": \"Group Child Size\",\n          \"description\": \"Group Child Size in pixels (affected by theme.scaling).\",\n          \"defaultValue\": 40.0,\n          \"required\": false,\n          \"isAdvanced\": false,\n          \"visibleIf\": [],\n          \"validation\": {\n            \"clamp\": \"reject\",\n            \"min\": 0.0,\n            \"max\": 100.0,\n            \"step\": 1.0\n          },\n          \"ui\": {\n            \"control\": \"slider\",\n            \"unit\": \"px\"\n          },\n          \"since\": \"1.0.0\"\n        },\n        {\n          \"type\": \"enum\",\n          \"name\": \"groupClipBehavior\",\n          \"label\": \"Group Clip Behavior\",\n          \"description\": \"Group Clip Behavior in pixels (affected by theme.scaling).\",\n          \"defaultValue\": \"none\",\n          \"required\": false,\n          \"isAdvanced\": false,\n          \"visibleIf\": [],\n          \"validation\": {\n            \"clamp\": \"reject\"\n          },\n          \"ui\": {\n            \"control\": \"select\"\n          },\n          \"since\": \"1.0.0\"\n        },\n        {\n          \"type\": \"number\",\n          \"name\": \"groupOffset\",\n          \"label\": \"Group Offset\",\n          \"descri