  "{installPath}/components/navigation/breadcrumb/_impl/core/breadcrumb_2.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../breadcrumb.dart';\n\n/// Breadcrumb defines a reusable type for this registry module.\nclass Breadcrumb extends StatelessWidget {\n  /// Arrow separator (>).\n  static const Widget arrowSeparator = _ArrowSeparator();\n\n  /// Slash separator (/).\n  static const Widget slashSeparator = _SlashSeparator();\n\n  /// The breadcrumb items rendered from root to current location.\n  final List<Widget> children;\n\n  /// Separator inserted between items.\n  final Widget? separator;\n\n  /// Padding around the breadcrumb strip.\n  final EdgeInsetsGeometry? padding;\n\n  /// Creates a breadcrumb navigation row.\n  const Breadcrumb({\n    super.key,\n    required this.children,\n    this.separator,\n    this.padding,\n  });\n\n  @override\n  /// Executes `build` behavior for this component/composite.\n  Widget build(BuildContext context) {\n    final compTheme = ComponentTheme.maybeOf<BreadcrumbTheme>(context);\n\n    /// Stores `sep` state/configuration for this implementation.\n    final sep = separator ?? compTheme?.separator ?? Breadcrumb.arrowSeparator;\n    final pad = styleValue(\n      widgetValue: padding,\n      themeValue: compTheme?.padding,\n      defaultValue: EdgeInsets.zero,\n    );\n    return ScrollConfiguration(\n      behavior: ScrollConfiguration.of(\n        context,\n      ).copyWith(scrollbars: false, dragDevices: {PointerDeviceKind.touch}),\n      child: SingleChildScrollView(\n        scrollDirection: Axis.horizontal,\n        child: Padding(\n          padding: pad,\n          child: Row(\n            children: [\n              if (children.length == 1) children[0].medium().foreground(),\n              if (children.length > 1)\n                for (var i = 0; i < children.length; i++)\n                  if (i == children.length - 1)\n                    children[i].medium().foreground()\n                  else\n                    /// Creates a `Row` instance.\n                    Row(children: [children[i].medium(), sep]),\n            ],\n          ).small(),\n        ),\n      ),\n    );\n  }\n}\n",
  "{installPath}/components/navigation/breadcrumb/breadcrumb.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\nimport 'dart:ui';\n\nimport 'package:flutter/widgets.dart';\n\nimport '../../../shared/icons/radix_icons.dart';\nimport '../../../shared/primitives/text.dart';\nimport '../../../shared/theme/theme.dart';\nimport '../../../shared/utils/style_value.dart';\npart '_impl/core/breadcrumb_2.dart';\npart '_impl/core/_slash_separator.dart';\npart '_impl/core/_arrow_separator.dart';\n\n/// Theme for [Breadcrumb].\nclass BreadcrumbTheme extends ComponentThemeData {\n  /// Separator widget between breadcrumb items.\n  final Widget? separator;\n\n  /// Padding surrounding the breadcrumb row.\n  final EdgeInsetsGeometry? padding;\n\n  /// Creates a [BreadcrumbTheme].\n  const BreadcrumbTheme({\n    super.themeDensity,\n    super.themeSpacing,\n    super.themeShadows,\n    this.separator,\n    this.padding,\n  });\n\n  /// Returns a copy of this theme with the given values replaced.\n  BreadcrumbTheme copyWith({\n    ValueGetter<Widget?>? separator,\n    ValueGetter<EdgeInsetsGeometry?>? padding,\n  }) {\n    return BreadcrumbTheme(\n      separator: separator == null ? this.separator : separator(),\n      padding: padding == null ? this.padding : padding(),\n    );\n  }\n\n  @override\n  /// Executes `operator ==` behavior for this component/composite.\n  bool operator ==(Object other) {\n    if (identical(this, other)) return true;\n    return other is BreadcrumbTheme &&\n        other.separator == separator &&\n        other.padding == padding;\n  }\n\n  @override\n  int get hashCode => Object.hash(separator, padding);\n}\n\n/// Navigation breadcrumb trail showing hierarchical path with customizable separators.\n",
  "{installPath}/components/form/input/_impl/core/input_above_below_feature.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../input.dart';\n\n/// Adds a custom widget above or below the text input area.\n///\n/// Use this feature to place helper content directly above or below the field.\nclass InputAboveBelowFeature extends InputFeature {\n  /// Widget shown above or below the input.\n  final Widget? child;\n\n  /// Position of the [child] relative to the input.\n  final InputFeaturePosition position;\n\n  /// Creates an [InputAboveBelowFeature].\n  const InputAboveBelowFeature({\n    super.visibility,\n    super.skipFocusTraversal,\n    this.child,\n    this.position = InputFeaturePosition.below,\n  });\n\n  /// Creates an [InputAboveBelowFeature] above the input.\n  const InputAboveBelowFeature.above(\n    this.child, {\n    super.visibility,\n    super.skipFocusTraversal,\n  }) : position = InputFeaturePosition.above;\n\n  /// Creates an [InputAboveBelowFeature] below the input.\n  const InputAboveBelowFeature.below(\n    this.child, {\n    super.visibility,\n    super.skipFocusTraversal,\n  }) : position = InputFeaturePosition.below;\n\n  /// Creates the `State` object for this widget.\n  @override\n  InputFeatureState createState() => _InputAboveBelowFeatureState();\n}\n",
  "{installPath}/components/form/input/_impl/core/input_auto_complete_feature.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../input.dart';\n\n/// Adds autocomplete functionality to the input field.\n///\n/// Displays a popover with suggestions as the user types. Suggestions are\n/// provided by the [querySuggestions] callback and can be selected to fill\n/// the input.\n///\n/// Example:\n/// ```dart\n/// TextField(\n///   features: [\n///     InputAutoCompleteFeature(\n///       querySuggestions: (query) async {\n///         return ['apple', 'apricot', 'avocado']\n///             .where((s) => s.startsWith(query));\n///       },\n///       child: const Text('Fruits'),\n///     ),\n///   ],\n/// )\n/// ```\nclass InputAutoCompleteFeature extends InputFeature {\n  /// Callback to provide suggestions for a given query.\n  final SuggestionBuilder querySuggestions;\n\n  /// Child widget displayed in the suggestion list.\n  final Widget child;\n\n  /// Constraints for the popover size.\n  final BoxConstraints? popoverConstraints;\n\n  /// Width constraint for the popover.\n  final PopoverConstraint? popoverWidthConstraint;\n\n  /// Anchor alignment for the popover.\n  final AlignmentDirectional? popoverAnchorAlignment;\n\n  /// Popover alignment relative to the anchor.\n  final AlignmentDirectional? popoverAlignment;\n\n  /// Autocomplete mode (e.g., popover or inline).\n  final AutoCompleteMode mode;\n\n  /// Creates an [InputAutoCompleteFeature].\n  ///\n  /// Parameters:\n  /// - [querySuggestions] (`SuggestionBuilder`, required): Provides suggestions.\n  /// - [child] (`Widget`, required): Content for suggestion items.\n  /// - [popoverConstraints] (`BoxConstraints?`, optional): Size constraints.\n  /// - [popoverWidthConstraint] (`PopoverConstraint?`, optional): Width constraint.\n  /// - [popoverAnchorAlignment] (`AlignmentDirectional?`, optional): Anchor alignment.\n  /// - [popoverAlignment] (`AlignmentDirectional?`, optional): Popover alignment.\n  /// - [mode] (`AutoCompleteMode`, required): Autocomplete display mode.\n  /// - [visibility] (`InputFeatureVisibility`, optional): Controls visibility.\n  /// - [skipFocusTraversal] (`bool`, optional): Whether to skip in focus order.\n  const InputAutoCompleteFeature({\n    super.visibility,\n    super.skipFocusTraversal,\n    required this.querySuggestions,\n    required this.child,\n    this.popoverConstraints,\n    this.popoverWidthConstraint,\n    this.popoverAnchorAlignment,\n    this.popoverAlignment,\n    this.mode = AutoCompleteMode.replaceWord,\n  });\n\n  /// Creates the `State` object for this widget.\n  @override\n  InputFeatureState createState() => _AutoCompleteFeatureState();\n}\n",
  "{installPath}/components/form/input/_impl/core/input_clear_feature.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../input.dart';\n\n/// Adds a clear button to the input field.\n///\n/// Provides a button that clears all text from the input when pressed.\n/// Commonly used to improve user experience by offering quick text removal.\n///\n/// Example:\n/// ```dart\n/// TextField(\n///   features: [\n///     InputClearFeature(\n///       position: InputFeaturePosition.trailing,\n///     ),\n///   ],\n/// )\n/// ```\nclass InputClearFeature extends InputFeature {\n  /// Position of the clear button.\n  final InputFeaturePosition position;\n\n  /// Custom icon for the clear button.\n  final Widget? icon;\n\n  /// Creates an [InputClearFeature].\n  ///\n  /// Parameters:\n  /// - [position] (`InputFeaturePosition`, default: `InputFeaturePosition.trailing`):\n  ///   Where to place the clear button.\n  /// - [icon] (`Widget?`, optional): Custom icon widget.\n  /// - [visibility] (`InputFeatureVisibility`, optional): Controls visibility.\n  /// - [skipFocusTraversal] (`bool`, optional): Whether to skip in focus order.\n  const InputClearFeature({\n    super.visibility,\n    super.skipFocusTraversal,\n    this.position = InputFeaturePosition.trailing,\n    this.icon,\n  });\n\n  /// Creates the `State` object for this widget.\n  @override\n  InputFeatureState createState() => _InputClearFeatureState();\n}\n",
  "{installPath}/components/form/input/_impl/core/input_copy_feature.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../input.dart';\n\n/// Adds a copy button to the input field.\n///\n/// Provides a button that copies the current input text to the clipboard.\n/// Useful for allowing users to easily copy generated or displayed content.\n///\n/// Example:\n/// ```dart\n/// TextField(\n///   controller: TextEditingController(text: 'Copy me!'),\n///   features: [\n///     InputCopyFeature(),\n///   ],\n/// )\n/// ```\nclass InputCopyFeature extends InputFeature {\n  /// Position of the copy button.\n  final InputFeaturePosition position;\n\n  /// Custom icon for the copy button.\n  final Widget? icon;\n\n  /// Creates an [InputCopyFeature].\n  ///\n  /// Parameters:\n  /// - [position] (`InputFeaturePosition`, default: `InputFeaturePosition.trailing`):\n  ///   Where to place the copy button.\n  /// - [icon] (`Widget?`, optional): Custom icon widget.\n  /// - [visibility] (`InputFeatureVisibility`, optional): Controls visibility.\n  /// - [skipFocusTraversal] (`bool`, optional): Whether to skip in focus order.\n  const InputCopyFeature({\n    super.visibility,\n    super.skipFocusTraversal,\n    this.position = InputFeaturePosition.trailing,\n    this.icon,\n  });\n\n  /// Creates the `State` object for this widget.\n  @override\n  InputFeatureState createState() => _InputCopyFeatureState();\n}\n",
  "{installPath}/components/form/input/_impl/core/input_hint_feature.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../input.dart';\n\n/// Adds a hint/info button to the input field with a popover.\n///\n/// Displays an icon button that shows a popover with additional information\n/// when clicked. Optionally supports keyboard shortcuts (F1) to open the hint.\n///\n/// Example:\n/// ```dart\n/// TextField(\n///   features: [\n///     InputHintFeature(\n///       popupBuilder: (context) => const Text('Enter your email'),\n///       icon: Icon(Icons.help),\n///     ),\n///   ],\n/// )\n/// ```\nclass InputHintFeature extends InputFeature {\n  /// Builder for the hint popover content.\n  final WidgetBuilder popupBuilder;\n\n  /// Custom icon to display (defaults to info icon).\n  final Widget? icon;\n\n  /// Position of the hint button.\n  final InputFeaturePosition position;\n\n  /// Whether to enable keyboard shortcut (F1) to show the hint.\n  final bool enableShortcuts;\n\n  /// Creates an [InputHintFeature].\n  ///\n  /// Parameters:\n  /// - [popupBuilder] (`WidgetBuilder`, required): Builds the hint content.\n  /// - [position] (`InputFeaturePosition`, default: `InputFeaturePosition.trailing`):\n  ///   Where to place the hint icon.\n  /// - [icon] (`Widget?`, optional): Custom icon widget.\n  /// - [enableShortcuts] (`bool`, default: `true`): Enable F1 keyboard shortcut.\n  /// - [visibility] (`InputFeatureVisibility`, optional): Controls visibility.\n  /// - [skipFocusTraversal] (`bool`, optional): Whether to skip in focus order.\n  const InputHintFeature({\n    super.visibility,\n    super.skipFocusTraversal,\n    required this.popupBuilder,\n    this.position = InputFeaturePosition.trailing,\n    this.icon,\n    this.enableShortcuts = true,\n  });\n\n  /// Creates the `State` object for this widget.\n  @override\n  InputFeatureState createState() => _InputHintFeatureState();\n}\n",
  "{installPath}/components/form/input/_impl/core/input_leading_feature.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../input.dart';\n\n/// Adds a custom widget to the leading (left) side of the input field.\n///\n/// Allows you to place any widget before the input text, such as icons,\n/// labels, or other decorative elements.\n///\n/// Example:\n/// ```dart\n/// TextField(\n///   features: [\n///     InputLeadingFeature(\n///       Icon(Icons.search),\n///     ),\n///   ],\n/// )\n/// ```\nclass InputLeadingFeature extends InputFeature {\n  /// The widget to display on the leading side.\n  final Widget prefix;\n\n  /// Creates an [InputLeadingFeature].\n  ///\n  /// Parameters:\n  /// - [prefix] (`Widget`, required): The widget to show before the input.\n  /// - [visibility] (`InputFeatureVisibility`, optional): Controls visibility.\n  /// - [skipFocusTraversal] (`bool`, optional): Whether to skip in focus order.\n  const InputLeadingFeature(\n    this.prefix, {\n    super.visibility,\n    super.skipFocusTraversal,\n  });\n\n  /// Creates the `State` object for this widget.\n  @override\n  InputFeatureState createState() => _InputLeadingFeatureState();\n}\n",
  "{installPath}/components/form/input/_impl/core/input_password_toggle_feature.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../input.dart';\n\n/// Adds a password visibility toggle feature to the input field.\n///\n/// Provides a button that allows users to toggle between showing and hiding\n/// password text. Supports both hold-to-reveal and toggle modes.\n///\n/// Example:\n/// ```dart\n/// TextField(\n///   obscureText: true,\n///   features: [\n///     InputPasswordToggleFeature(\n///       mode: PasswordPeekMode.toggle,\n///     ),\n///   ],\n/// )\n/// ```\nclass InputPasswordToggleFeature extends InputFeature {\n  /// The mode for password peeking behavior.\n  final PasswordPeekMode mode;\n\n  /// Position of the toggle button.\n  final InputFeaturePosition position;\n\n  /// Icon to display when password is hidden.\n  final Widget? icon;\n\n  /// Icon to display when password is shown.\n  final Widget? iconShow;\n\n  /// Creates an [InputPasswordToggleFeature].\n  ///\n  /// Parameters:\n  /// - [mode] (`PasswordPeekMode`, default: `PasswordPeekMode.toggle`):\n  ///   Toggle or hold behavior.\n  /// - [position] (`InputFeaturePosition`, default: `InputFeaturePosition.trailing`):\n  ///   Where to place the toggle.\n  /// - [icon] (`Widget?`, optional): Custom icon for hidden state.\n  /// - [iconShow] (`Widget?`, optional): Custom icon for visible state.\n  /// - [visibility] (`InputFeatureVisibility`, optional): Controls visibility.\n  /// - [skipFocusTraversal] (`bool`, optional): Whether to skip in focus order.\n  const InputPasswordToggleFeature({\n    super.visibility,\n    this.icon,\n    this.iconShow,\n    this.mode = PasswordPeekMode.toggle,\n    this.position = InputFeaturePosition.trailing,\n    super.skipFocusTraversal,\n  });\n\n  /// Creates the `State` object for this widget.\n  @override\n  InputFeatureState createState() => _InputPasswordToggleFeatureState();\n}\n",
  "{installPath}/components/form/input/_impl/core/input_paste_feature.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../input.dart';\n\n/// Adds a paste button to the input field.\n///\n/// Provides a button that pastes content from the clipboard into the input.\n/// Useful for improving user experience when entering copied data.\n///\n/// Example:\n/// ```dart\n/// TextField(\n///   features: [\n///     InputPasteFeature(\n///       position: InputFeaturePosition.trailing,\n///     ),\n///   ],\n/// )\n/// ```\nclass InputPasteFeature extends InputFeature {\n  /// Position of the paste button.\n  final InputFeaturePosition position;\n\n  /// Custom icon for the paste button.\n  final Widget? icon;\n\n  /// Creates an [InputPasteFeature].\n  ///\n  /// Parameters:\n  /// - [position] (`InputFeaturePosition`, default: `InputFeaturePosition.trailing`):\n  ///   Where to place the paste button.\n  /// - [icon] (`Widget?`, optional): Custom icon widget.\n  /// - [visibility] (`InputFeatureVisibility`, optional): Controls visibility.\n  /// - [skipFocusTraversal] (`bool`, optional): Whether to skip in focus order.\n  const InputPasteFeature({\n    super.visibility,\n    super.skipFocusTraversal,\n    this.position = InputFeaturePosition.trailing,\n    this.icon,\n  });\n\n  /// Creates the `State` object for this widget.\n  @override\n  InputFeatureState createState() => _InputPasteFeatureState();\n}\n",
  "{installPath}/components/form/input/_impl/core/input_revalidate_feature.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../input.dart';\n\n/// Adds a revalidate button to the input field.\n///\n/// Provides a button that triggers form validation when pressed.\n/// Useful for manually triggering validation after user input.\n///\n/// Example:\n/// ```dart\n/// TextField(\n///   features: [\n///     InputRevalidateFeature(),\n///   ],\n/// )\n/// ```\nclass InputRevalidateFeature extends InputFeature {\n  /// Position of the revalidate button.\n  final InputFeaturePosition position;\n\n  /// Custom icon for the revalidate button.\n  final Widget? icon;\n\n  /// Creates an [InputRevalidateFeature].\n  ///\n  /// Parameters:\n  /// - [position] (`InputFeaturePosition`, default: `InputFeaturePosition.trailing`):\n  ///   Where to place the revalidate button.\n  /// - [icon] (`Widget?`, optional): Custom icon widget.\n  /// - [visibility] (`InputFeatureVisibility`, optional): Controls visibility.\n  /// - [skipFocusTraversal] (`bool`, optional): Whether to skip in focus order.\n  const InputRevalidateFeature({\n    super.visibility,\n    super.skipFocusTraversal,\n    this.position = InputFeaturePosition.trailing,\n    this.icon,\n  });\n\n  /// Creates the `State` object for this widget.\n  @override\n  InputFeatureState createState() => _InputRevalidateFeatureState();\n}\n",
  "{installPath}/components/form/input/_impl/core/input_spinner_feature.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../input.dart';\n\n/// Adds spinner controls (increment/decrement) to numeric input fields.\n///\n/// Provides up/down buttons to adjust numeric values in fixed steps.\n/// Optionally supports gesture-based adjustments (e.g., drag to change value).\n///\n/// Example:\n/// ```dart\n/// TextField(\n///   keyboardType: TextInputType.number,\n///   features: [\n///     InputSpinnerFeature(\n///       step: 5.0,\n///       enableGesture: true,\n///     ),\n///   ],\n/// )\n/// ```\nclass InputSpinnerFeature extends InputFeature {\n  /// The amount to increment or decrement on each step.\n  final double step;\n\n  /// Whether to enable gesture-based value adjustment.\n  final bool enableGesture;\n\n  /// Default value when the input is invalid or empty.\n  final double? invalidValue;\n\n  /// Minimum allowed value.\n  final double? min;\n\n  /// Maximum allowed value.\n  final double? max;\n\n  /// Creates an [InputSpinnerFeature].\n  ///\n  /// Parameters:\n  /// - [step] (`double`, default: `1.0`): Increment/decrement step size.\n  /// - [enableGesture] (`bool`, default: `true`): Enable drag gestures.\n  /// - [invalidValue] (`double?`, default: `0.0`): Fallback value for invalid input.\n  /// - [min] (`double?`, optional): Minimum allowed value.\n  /// - [max] (`double?`, optional): Maximum allowed value.\n  /// - [visibility] (`InputFeatureVisibility`, optional): Controls visibility.\n  /// - [skipFocusTraversal] (`bool`, optional): Whether to skip in focus order.\n  const InputSpinnerFeature({\n    super.visibility,\n    super.skipFocusTraversal,\n    this.step = 1.0,\n    this.enableGesture = true,\n    this.invalidValue = 0.0,\n    this.min,\n    this.max,\n  });\n\n  /// Creates the `State` object for this widget.\n  @override\n  InputFeatureState createState() => _InputSpinnerFeatureState();\n}\n",
  "{installPath}/components/form/input/_impl/core/input_stepper_button_feature.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../input.dart';\n\n/// Adds a single increment button to numeric input fields.\nclass InputStepperButtonFeature extends InputFeature {\n  /// The amount to increment on each press.\n  final double step;\n\n  /// Default value when the input is invalid or empty.\n  final double? invalidValue;\n\n  /// Minimum allowed value.\n  final double? min;\n\n  /// Maximum allowed value.\n  final double? max;\n\n  /// Position of the increment button.\n  final InputFeaturePosition position;\n\n  /// Custom icon for the increment button.\n  final Widget? icon;\n\n  /// Creates an [InputStepperButtonFeature].\n  const InputStepperButtonFeature({\n    super.visibility,\n    super.skipFocusTraversal,\n    this.step = 1.0,\n    this.invalidValue = 0.0,\n    this.min,\n    this.max,\n    this.position = InputFeaturePosition.trailing,\n    this.icon = const Icon(LucideIcons.plus),\n  });\n\n  /// Creates a decrement button feature for numeric inputs.\n  const InputStepperButtonFeature.decrement({\n    super.visibility,\n    super.skipFocusTraversal,\n    this.step = -1.0,\n    this.invalidValue = 0.0,\n    this.min,\n    this.max,\n    this.position = InputFeaturePosition.trailing,\n    this.icon = const Icon(LucideIcons.minus),\n  });\n\n  /// Creates the `State` object for this widget.\n  @override\n  InputFeatureState createState() => _InputStepperButtonFeatureState();\n}\n",
