  "{installPath}/components/navigation/tabs/_impl/core/tab_item_painter.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../tabs.dart';\n\n/// _TabItemPainter defines a reusable type for this registry module.\nclass _TabItemPainter extends CustomPainter {\n  /// Stores `borderRadius` state/configuration for this implementation.\n  final BorderRadius borderRadius;\n\n  /// Stores `backgroundColor` state/configuration for this implementation.\n  final Color backgroundColor;\n\n  /// Stores `borderColor` state/configuration for this implementation.\n  final Color borderColor;\n\n  /// Stores `isFocused` state/configuration for this implementation.\n  final bool isFocused;\n\n  /// Stores `borderWidth` state/configuration for this implementation.\n  final double borderWidth;\n\n  /// Creates a `_TabItemPainter` instance.\n  _TabItemPainter({\n    required this.borderRadius,\n    required this.backgroundColor,\n    required this.isFocused,\n    required this.borderWidth,\n    required this.borderColor,\n  });\n\n  @override\n  /// Executes `shouldRepaint` behavior for this component/composite.\n  bool shouldRepaint(covariant _TabItemPainter oldDelegate) {\n    return oldDelegate.borderRadius != borderRadius ||\n        oldDelegate.backgroundColor != backgroundColor ||\n        oldDelegate.isFocused != isFocused ||\n        oldDelegate.borderWidth != borderWidth ||\n        oldDelegate.borderColor != borderColor;\n  }\n\n  /// Executes `createPath` behavior for this component/composite.\n  Path createPath(Size size, [bool closed = false]) {\n    Path path = Path();\n\n    /// Stores `adjustment` state/configuration for this implementation.\n    double adjustment = borderWidth;\n    path.moveTo(-borderRadius.bottomLeft.x, size.height + adjustment);\n\n    /// Creates a `path.quadraticBezierTo` instance.\n    path.quadraticBezierTo(\n      0,\n      size.height,\n      0,\n      size.height - borderRadius.bottomLeft.y,\n    );\n    path.lineTo(0, borderRadius.topLeft.y);\n    path.quadraticBezierTo(0, 0, borderRadius.topLeft.x, 0);\n    path.lineTo(size.width - borderRadius.topRight.x, 0);\n    path.quadraticBezierTo(size.width, 0, size.width, borderRadius.topRight.y);\n    path.lineTo(size.width, size.height - borderRadius.bottomRight.y);\n\n    /// Creates a `path.quadraticBezierTo` instance.\n    path.quadraticBezierTo(\n      size.width,\n      size.height,\n      size.width + borderRadius.bottomRight.x,\n      size.height + adjustment,\n    );\n    if (closed) {\n      path.close();\n    }\n    return path;\n  }\n\n  @override\n  /// Executes `paint` behavior for this component/composite.\n  void paint(Canvas canvas, Size size) {\n    if (!isFocused) {\n      return;\n    }\n    Path path = createPath(size, true);\n\n    /// Creates a `canvas.drawPath` instance.\n    canvas.drawPath(\n      path,\n\n      /// Creates a `Paint` instance.\n      Paint()\n        ..color = backgroundColor\n        ..style = PaintingStyle.fill,\n    );\n\n    Path borderPath = createPath(size);\n\n    /// Creates a `canvas.drawPath` instance.\n    canvas.drawPath(\n      borderPath,\n\n      /// Creates a `Paint` instance.\n      Paint()\n        ..color = borderColor\n        ..style = PaintingStyle.stroke\n        ..strokeWidth = borderWidth,\n    );\n  }\n}\n",
  "{installPath}/components/navigation/tabs/_impl/core/tab_list.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../tabs.dart';\n\n/// TabList defines a reusable type for this registry module.\nclass TabList extends StatelessWidget {\n  /// List of tab child widgets to display in the tab list.\n  ///\n  /// Type: `List<TabChild>`. Each TabChild represents one selectable tab\n  /// with its own label and optional content. The tabs are displayed in\n  /// the order provided in the list.\n  final List<TabChild> children;\n\n  /// Index of the currently active/selected tab.\n  ///\n  /// Type: `int`. Zero-based index indicating which tab is currently active.\n  /// Must be within the bounds of the [children] list. The active tab\n  /// receives special styling and the indicator line.\n  final int index;\n\n  /// Callback invoked when a tab is selected.\n  ///\n  /// Type: `ValueChanged<int>?`. Called with the index of the newly selected\n  /// tab when the user taps on a tab button. If null, tabs are not interactive.\n  final ValueChanged<int>? onChanged;\n\n  /// Creates a [TabList] with horizontal tab selection.\n  ///\n  /// Configures a tab list widget that displays a horizontal row of selectable\n  /// tab buttons with visual feedback for the active tab.\n  ///\n  /// Parameters:\n  /// - [key] (Key?): Widget identifier for the widget tree\n  /// - [children] (`List<TabChild>`, required): List of tab items to display\n  /// - [index] (int, required): Index of the currently active tab\n  /// - [onChanged] (`ValueChanged<int>?`, required): Callback for tab selection\n  ///\n  /// Example:\n  /// ```dart\n  /// TabList(\n  ///   index: selectedIndex,\n  ///   onChanged: (newIndex) {\n  ///     setState(() {\n  ///       selectedIndex = newIndex;\n  ///       // Update content based on new tab selection\n  ///     });\n  ///   },\n  ///   children: [\n  ///     TabChild(child: Text('Overview')),\n  ///     TabChild(child: Text('Details')),\n  ///     TabChild(child: Text('Settings')),\n  ///   ],\n  /// )\n  /// ```\n  const TabList({\n    super.key,\n    required this.children,\n    required this.index,\n    required this.onChanged,\n  });\n\n  Widget _childBuilder(\n    BuildContext context,\n    TabContainerData data,\n    Widget child,\n  ) {\n    final theme = Theme.of(context);\n    final compTheme = ComponentTheme.maybeOf<TabListTheme>(context);\n    final indicatorColor = styleValue(\n      defaultValue: theme.colorScheme.primary,\n      themeValue: compTheme?.indicatorColor,\n    );\n    final indicatorHeight = styleValue(\n      defaultValue: 2 * theme.scaling,\n      themeValue: compTheme?.indicatorHeight,\n    );\n    child = TabButton(\n      enabled: data.onSelect != null,\n      onPressed: () {\n        data.onSelect?.call(data.index);\n      },\n      child: child,\n    );\n    return Stack(\n      fit: StackFit.passthrough,\n      children: [\n        data.index == index ? child.foreground() : child.muted(),\n        if (data.index == index)\n          /// Creates a `Positioned` instance.\n          Positioned(\n            bottom: 0,\n            left: 0,\n            right: 0,\n            child: Container(height: indicatorHeight, color: indicatorColor),\n          ),\n      ],\n    );\n  }\n\n  @override\n  /// Executes `build` behavior for this component/composite.\n  Widget build(BuildContext context) {\n    final theme = Theme.of(context);\n\n    /// Stores `scaling` state/configuration for this implementation.\n    final scaling = theme.scaling;\n    final compTheme = ComponentTheme.maybeOf<TabListTheme>(context);\n    final borderColor = styleValue(\n      defaultValue: theme.colorScheme.border,\n      themeValue: compTheme?.borderColor,\n    );\n    final borderWidth = styleValue(\n      defaultValue: 1 * scaling,\n      themeValue: compTheme?.borderWidth,\n    );\n    return TabContainer(\n      selected: index,\n      onSelect: onChanged,\n      builder: (context, children) {\n        return Container(\n          decoration: BoxDecoration(\n            border: Border(\n              bottom: BorderSide(color: borderColor, width: borderWidth),\n            ),\n          ),\n          child: Row(children: children),\n        );\n      },\n      childBuilder: _childBuilder,\n      children: children,\n    );\n  }\n}\n",
  "{installPath}/components/navigation/tabs/_impl/core/tab_pane_data.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../tabs.dart';\n\n/// TabPaneData defines a reusable type for this registry module.\nclass TabPaneData<T> extends SortableData<T> {\n  /// Creates a [TabPaneData] wrapper for tab content.\n  ///\n  /// Wraps the provided data for use in sortable tab pane operations.\n  ///\n  /// Parameters:\n  /// - [data] (T): The data to associate with this tab item\n  const TabPaneData(super.data);\n}\n\n/// Builder function for creating tab child widgets from tab pane data.\n///\n/// Takes the build context, tab data, and index to create a TabChild widget\n/// that represents the visual appearance of each tab button.\n///\n/// Parameters:\n/// - [context] (BuildContext): Build context for theme access\n/// - [item] (`TabPaneData<T>`): The data for this specific tab\n/// - [index] (int): Zero-based index of this tab in the list\n///\n/// Returns: A [TabChild] widget for the tab button\n",
  "{installPath}/components/navigation/tabs/_impl/core/tab_pane_typedefs.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../tabs.dart';\n\n/// Type alias for `TabPaneItemBuilder` used by public or internal APIs.\ntypedef TabPaneItemBuilder<T> =\n    TabChild Function(BuildContext context, TabPaneData<T> item, int index);\n\n/// A comprehensive tab pane widget with sortable tabs and integrated content display.\n///\n/// TabPane provides a complete tab interface that combines a sortable tab bar with\n/// a content display area. It supports drag-and-drop reordering of tabs, scrollable\n/// tab overflow, and customizable leading/trailing elements in the tab bar.\n///\n/// The widget manages both the tab selection state and the tab ordering, providing\n/// callbacks for both focus changes and sort operations. The tab bar is horizontally\n/// scrollable when tabs exceed the available width, with fade effects at the edges.\n///\n/// Features:\n/// - Drag-and-drop sortable tabs with visual feedback\n/// - Horizontal scrolling with edge fade effects for tab overflow\n/// - Integrated content area with customizable styling\n/// - Leading and trailing widget support in the tab bar\n/// - Custom tab rendering through builder patterns\n/// - Comprehensive theming and styling options\n/// - Automatic focus management during sorting operations\n///\n/// The content area is styled as a card-like container that appears above the\n/// tab bar, creating a cohesive tabbed interface suitable for complex applications.\n///\n/// Example:\n/// ```dart\n/// TabPane<String>(\n///   items: [\n///     TabPaneData('tab1'),\n///     TabPaneData('tab2'),\n///     TabPaneData('tab3'),\n///   ],\n///   focused: currentTab,\n///   onFocused: (index) => setState(() => currentTab = index),\n///   onSort: (newOrder) => setState(() => tabOrder = newOrder),\n///   itemBuilder: (context, item, index) => TabChild(\n///     child: Text(item.data),\n///   ),\n///   child: IndexedStack(\n///     index: currentTab,\n///     children: tabContent,\n///   ),\n/// )\n/// ```\n",
  "{installPath}/components/navigation/tabs/_impl/core/tab_pane_widget.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../tabs.dart';\n\n/// TabPane defines a reusable type for this registry module.\nclass TabPane<T> extends StatefulWidget {\n  /// List of tab data items to display in the tab pane.\n  ///\n  /// Type: `List<TabPaneData<T>>`. Each item contains the data for one tab\n  /// and will be passed to the [itemBuilder] to create the visual representation.\n  final List<TabPaneData<T>> items;\n\n  /// Builder function to create tab child widgets from data items.\n  ///\n  /// Type: `TabPaneItemBuilder<T>`. Called for each tab item to create the\n  /// visual representation in the tab bar. Should return a TabChild widget.\n  final TabPaneItemBuilder<T> itemBuilder;\n\n  /// Callback invoked when tabs are reordered through drag-and-drop.\n  ///\n  /// Type: `ValueChanged<List<TabPaneData<T>>>?`. Called with the new tab\n  /// order when sorting operations complete. If null, sorting is disabled.\n  final ValueChanged<List<TabPaneData<T>>>? onSort;\n\n  /// Index of the currently focused/selected tab.\n  ///\n  /// Type: `int`. Zero-based index of the active tab. The focused tab receives\n  /// special visual styling and its content is typically displayed.\n  final int focused;\n\n  /// Callback invoked when the focused tab changes.\n  ///\n  /// Type: `ValueChanged<int>`. Called when a tab is selected either through\n  /// user interaction or programmatic changes during sorting operations.\n  final ValueChanged<int> onFocused;\n\n  /// Widgets displayed at the leading edge of the tab bar.\n  ///\n  /// Type: `List<Widget>`, default: `[]`. These widgets appear before the\n  /// scrollable tab area, useful for controls or branding elements.\n  final List<Widget> leading;\n\n  /// Widgets displayed at the